209	/** Tags the pinned client's own `TAG_REG` would find in this content. */
210	export function memosTagsInContent(content: string): string[] {
211		const found: string[] = [];
212		for (const match of content.matchAll(MEMO_TAG)) {
213			const tag = match.groups?.tag;
214			if (tag !== undefined && tag.length > 0 && !found.includes(tag)) found.push(tag);
215		}
216		return found;
217	}
