605				return {
606					endpoint: 'user.list',
607					response: authenticated(() => envelope(structuredClone(users))),
608				};
609			if (request.pathname === '/api/user' && request.method === 'POST')
610				return {
611					endpoint: 'user.create',
612					response: authenticated((user) => {
613						if (user.role !== 'OWNER')
614							return failure(
615								403,
616								'forbidden',
617								'Memos synthetic projection lets only the owner create members',
618							);
619						const created = createUser(parsedBody(body), 'USER');
620						return 'id' in created ? envelope(structuredClone(created)) : created;
621					}),
622				};
623			if (request.pathname === '/api/user/me' && request.method === 'GET')
624				return {
625					endpoint: 'user.me.get',
626					response: authenticated((user) => envelope(structuredClone(user))),
627				};
628			if (request.pathname === '/api/user/me' && request.method === 'PATCH')
629				return {
630					endpoint: 'user.me.patch',
631					response: authenticated((user) => patchMe(user, parsedBody(body))),
632				};
633			return null;
634		};
