658					endpoint: 'memo.patch',
659					response: authenticated((user) => patchMemo(user, memoId, parsedBody(body))),
660				};
661			if (memoId !== null && request.method === 'DELETE')
662				return {
663					endpoint: 'memo.delete',
664					response: authenticated((user) => deleteMemo(user, memoId)),
665				};
666			return null;
667		};
668	
669		const handleShortcut = (request: MemosApiRequest, body: Buffer): Handled | null => {
670			if (request.pathname === '/api/shortcut' && request.method === 'GET')
671				return {
672					endpoint: 'shortcut.list',
673					response: authenticated((user) =>
674						envelope(
675							structuredClone(
676								shortcuts
677									.filter((record) => record.creatorId === user.id)
678									.sort(byCreated),
679							),
680						),
681					),
682				};
683			if (request.pathname === '/api/shortcut' && request.method === 'POST')
684				return {
685					endpoint: 'shortcut.create',
686					response: authenticated((user) => createShortcut(user, parsedBody(body))),
687				};
688			const shortcutId = numericSuffix(request.pathname, '/api/shortcut/');
689			if (shortcutId !== null && request.method === 'PATCH')
