733				};
734			const handled =
735				handleUser(request, body) ?? handleMemo(request, body) ?? handleShortcut(request, body);
736			return (
737				handled ?? {
738					endpoint: '',
739					response: unknownPath(request.method, request.pathname),
740				}
741			);
742		};
743	
744		const record = (
745			request: MemosApiRequest,
746			endpoint: string | null,
747			decision: MemosProjectionDecision,
748			response: MemosApiResponse | null,
749		): void => {
750			sequence += 1;
751			records.push({
752				sequence,
753				method: request.method,
754				pathname: request.pathname,
755				search: request.search,
756				endpoint,
757				decision,
758				status: response?.status ?? null,
759				authenticated: session !== null,
760				requestSha256: sha256(request.body),
761				responseSha256: response === null ? null : sha256(response.body),
762			});
763		};
764	
765		const api = async (request: MemosApiRequest): Promise<MemosApiResponse | null> => {
766			if (!request.pathname.startsWith('/api/')) {
767				record(request, null, 'declined-non-api', null);
768				return null;
769			}
770			const handled = handle(request);
771			const endpoint = handled.endpoint.length === 0 ? null : handled.endpoint;
772			const decision: MemosProjectionDecision =
773				endpoint === null
774					? 'refused-unknown'
775					: handled.response.status === 501
776						? 'refused-unprojected'
777						: 'served';
778			record(request, endpoint, decision, handled.response);
