784			ledger: () => records.map((entry) => ({ ...entry })),
785			sessionUserId: () => session,
786			memos: () => structuredClone(memos),
787			shortcuts: () => structuredClone(shortcuts),
788			users: () => structuredClone(users),
789		};
790	}
